"use strict";(globalThis.webpackChunktech_writing_portfolio=globalThis.webpackChunktech_writing_portfolio||[]).push([[816],{17017(e,i,t){t.r(i),t.d(i,{assets:()=>d,contentTitle:()=>s,default:()=>h,frontMatter:()=>o,metadata:()=>n,toc:()=>r});const n=JSON.parse('{"id":"process-governance/process-improvement","title":"Finding and Fixing a Broken Process","description":"Why scheduled SOP reviews stopped happening in practice, and the workflow automation built to fix it.","source":"@site/docs/process-governance/process-improvement.md","sourceDirName":"process-governance","slug":"/process-governance/process-improvement","permalink":"/tech-writing-portfolio/previews/pr-5/docs/process-governance/process-improvement","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1789979870000,"frontMatter":{"id":"process-improvement","title":"Finding and Fixing a Broken Process","description":"Why scheduled SOP reviews stopped happening in practice, and the workflow automation built to fix it.","sidebar_label":"Process Improvement","slug":"/process-governance/process-improvement"},"sidebar":"processGovernanceSidebar","previous":{"title":"Ownership & Review Model","permalink":"/tech-writing-portfolio/previews/pr-5/docs/process-governance/governance"}}');var a=t(74848),I=t(28453);const o={id:"process-improvement",title:"Finding and Fixing a Broken Process",description:"Why scheduled SOP reviews stopped happening in practice, and the workflow automation built to fix it.",sidebar_label:"Process Improvement",slug:"/process-governance/process-improvement"},s="Finding and fixing a broken process",d={},r=[{value:"Where this breaks down",id:"where-this-breaks-down",level:2},{value:"Mapping it",id:"mapping-it",level:2},{value:"What I built",id:"what-i-built",level:2},{value:"The other half of this: Capturing what people actually do",id:"the-other-half-of-this-capturing-what-people-actually-do",level:2},{value:"What&#39;s next",id:"whats-next",level:2}];function g(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",img:"img",p:"p",...(0,I.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(i.header,{children:(0,a.jsx)(i.h1,{id:"finding-and-fixing-a-broken-process",children:"Finding and fixing a broken process"})}),"\n",(0,a.jsxs)(i.p,{children:["Ownership on paper and ownership in practice aren't the same thing. That gap shows up the moment you check how many of the quarterly SOP reviews defined in the ",(0,a.jsx)(i.a,{href:"./governance",children:"ownership and review model"})," actually happened on schedule."]}),"\n",(0,a.jsx)(i.h2,{id:"where-this-breaks-down",children:"Where this breaks down"}),"\n",(0,a.jsx)(i.p,{children:"Naming an owner and setting a review date doesn't hold up on its own, and the gap is a predictable one: the review date sits on the page, with nothing pointing at it. Someone has to remember to check, for every page they own, on a schedule they'd have to track themselves \u2013 and almost nobody keeps that up by memory alone, me included. Owners get named, dates get set, and reviews still don't happen on schedule."}),"\n",(0,a.jsx)(i.p,{children:"That's more of a process problem than a documentation one. The pages themselves are fine \u2013 it's the thing meant to keep them that way that's missing a trigger."}),"\n",(0,a.jsx)(i.h2,{id:"mapping-it",children:"Mapping it"}),"\n",(0,a.jsx)(i.p,{children:"I sketched out the state this tends to fall into, next to the shorter future state I'd want instead:"}),"\n",(0,a.jsx)(i.p,{children:(0,a.jsx)(i.img,{alt:"Review-reminder process before and after: current state shows a review date set on a page, nothing checks it, the page goes overdue unnoticed, and it&#39;s found by chance or the next audit; future state shows a review date set on a page, a weekly automated check, the owner nudged two weeks before it&#39;s due, and a second nudge if it goes overdue",src:t(99568).A+"",width:"707",height:"400"})}),"\n",(0,a.jsx)(i.p,{children:"Three of the four steps on the left involve nobody doing anything, which is usually the sign that a process is relying on a person's memory instead of a system."}),"\n",(0,a.jsx)(i.h2,{id:"what-i-built",children:"What I built"}),"\n",(0,a.jsx)(i.p,{children:"A small scheduled workflow \u2013 the kind of thing you'd put together in n8n or Tines rather than anything custom-coded \u2013 that reads the review-due date on every page in the space once a week, and posts a message to the owner directly when a page is within two weeks of its due date, with a second, more pointed message if it goes overdue. It's not sophisticated. It doesn't need to be. It just moves the trigger off a person's memory and onto a clock."}),"\n",(0,a.jsxs)(i.p,{children:["The same weekly check also looks up whether each owner's account is still active in the directory. If it isn't, the page gets flagged for reassignment straight away, instead of waiting on the standing ",(0,a.jsx)(i.a,{href:"./governance",children:"offboarding step"})," to catch it. That's the specific gap that left nineteen pages ownerless before any of this existed \u2013 someone leaves, the offboarding checklist gets missed or half-followed, and the page just sits there until the next audit finds it."]}),"\n",(0,a.jsx)(i.p,{children:"Overdue reviews dropped off within a month of turning it on. Not because anyone got better at remembering \u2013 because they stopped having to."}),"\n",(0,a.jsx)(i.h2,{id:"the-other-half-of-this-capturing-what-people-actually-do",children:"The other half of this: Capturing what people actually do"}),"\n",(0,a.jsxs)(i.p,{children:["The reminder fixed timing. It didn't fix accuracy, which is a separate problem I ran into while writing the ",(0,a.jsx)(i.a,{href:"./template-sop",children:"site provisioning SOP"}),". Picturing what the on-call engineer would actually do, step by step, against what the written procedure said turned up three places where the two would diverge \u2013 the kind of detail a straight description-from-memory wouldn't catch. It's the reason I'd rather sit with someone during a real change and write down what happens than take a page at its word."]}),"\n",(0,a.jsx)(i.p,{children:"I'd apply the same method to the change log process: picture sitting with a PM and tracing two change requests end to end. That surfaces a step where ticket status was being copied manually into a page nobody downstream was actually reading, because it used to matter and the reason it mattered was long gone. I wrote up a shorter version of the process and a simple flowchart of the change lifecycle, and that step came out."}),"\n",(0,a.jsx)(i.p,{children:'Neither of these looked like documentation problems on the surface \u2013 the symptom was "the page is wrong" or "nobody\'s doing what the page says." The actual problem, both times, was upstream in the process itself. That\'s the part of this work I find genuinely interesting: the writing is often the easy half.'}),"\n",(0,a.jsx)(i.h2,{id:"whats-next",children:"What's next"}),"\n",(0,a.jsx)(i.p,{children:"The reminder system was the first automation I put in, not the last one I'd want. Two more are on my list: nudging new-page authors toward the right template before a page goes live, instead of catching drift at the next review, and automatically drafting a Troubleshooting page from a closed ticket the moment something new gets resolved, so the write-up starts before anyone has to remember to do it. Neither is built yet \u2013 the reminder system got the time first because it was the most widespread problem."})]})}function h(e={}){const{wrapper:i}={...(0,I.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(g,{...e})}):g(e)}},99568(e,i,t){t.d(i,{A:()=>n});const n="data:image/svg+xml;base64,"},28453(e,i,t){t.d(i,{R:()=>o,x:()=>s});var n=t(96540);const a={},I=n.createContext(a);function o(e){const i=n.useContext(I);return n.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function s(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),n.createElement(I.Provider,{value:i},e.children)}}}]);